CREATE     PROCEDURE [synapse_fo].[usp_Insert_SYSTEMPARAMETERS]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:30:00
	Description: Insert stored procedure for SYSTEMPARAMETERS from synapse finops datalake to BI
*/
BEGIN
	INSERT INTO [synapse_fo].[SYSTEMPARAMETERS]
	(
		[CHARTOFACCOUNTSDELIMITER],
		[DataLakeModified_DateTime],
		--[FileName],
		--[KEY_],
		[LastProcessedChange_DateTime],
		--[LSN],
		[MODIFIEDBY],
		[MODIFIEDDATETIME],
		[ODATAALLOWNULLFORENUMKEYVALUE],
		[ODATABUILDMETADATACACHEONAOSSTARTUP],
		[PARTITION],
		[POWERPORTALANONYMOUSUSERID],
		[RECID],
		[RECVERSION],
		[SRSMAXROW_CN],
		--[SysRowId],
		[SYSTEMCURRENCYCODE],
		[SYSTEMEXCHANGERATETYPE],
		[SYSTEMLANGUAGEID],
		[SYSTEMLEGALTERMSURL],
		[SYSTEMLINENUMBERINCREMENT],
		[SYSTEMPRIVACYSTATEMENTURL],
		[THAISOFTWARESEQNO],
		[USEADVCERTIFICATESTORE],
		[USELEGACYQUERYRELATIONS]
	)
	SELECT 
		stg.[CHARTOFACCOUNTSDELIMITER],
		stg.[DataLakeModified_DateTime],
		--stg.--[FileName],
		--stg.[KEY_],
		stg.[LastProcessedChange_DateTime],
		--stg.--[LSN],
		stg.[MODIFIEDBY],
		stg.[MODIFIEDDATETIME],
		stg.[ODATAALLOWNULLFORENUMKEYVALUE],
		stg.[ODATABUILDMETADATACACHEONAOSSTARTUP],
		stg.[PARTITION],
		stg.[POWERPORTALANONYMOUSUSERID],
		stg.[RECID],
		stg.[RECVERSION],
		stg.[SRSMAXROW_CN],
		--stg.--[SysRowId],
		stg.[SYSTEMCURRENCYCODE],
		stg.[SYSTEMEXCHANGERATETYPE],
		stg.[SYSTEMLANGUAGEID],
		stg.[SYSTEMLEGALTERMSURL],
		stg.[SYSTEMLINENUMBERINCREMENT],
		stg.[SYSTEMPRIVACYSTATEMENTURL],
		stg.[THAISOFTWARESEQNO],
		stg.[USEADVCERTIFICATESTORE],
		stg.[USELEGACYQUERYRELATIONS]	
	FROM [staging_fo].[SYSTEMPARAMETERS] stg
		LEFT JOIN [synapse_fo].[SYSTEMPARAMETERS] tgt
			ON stg.[RECID] = tgt.[RECID] 
		
	WHERE tgt.[RECID] IS NULL
END
